-- MP-0060: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pbb' and type='party') then raise exception 'MP-0060: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='supp' and type='party') then raise exception 'MP-0060: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('yusuf-abd-wahab','ahmad-johnie-zawawi','huang-tiong-sii') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0060: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('tanjong manis','igan','sarikei') and slug not in ('yusuf-abd-wahab','ahmad-johnie-zawawi','huang-tiong-sii')) then raise exception 'MP-0060: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0060:%' and (m.source_type <> 'editorial' or e.slug not in ('yusuf-abd-wahab','ahmad-johnie-zawawi','huang-tiong-sii') or m.import_key not like 'MP-0060:' || e.slug || ':%')) then raise exception 'MP-0060: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'yusuf-abd-wahab','Yusuf Abd Wahab','government','Member of the Dewan Rakyat','Tanjong Manis','Sarawak','Yusuf Abd Wahab represents Tanjong Manis, Sarawak, in the Dewan Rakyat. Affiliated with PBB.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4245','/portraits/yusuf-abd-wahab.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P206.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4245"}, {"label": "PBB · current 2025–2028 council", "url": "https://suarasarawak.my/senarai-penuh-majlis-kerja-tertinggi-mkt-pbb-sesi-2025-2028/"}]'::jsonb from public.entities parent where parent.slug='pbb' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ahmad-johnie-zawawi','Ahmad Johnie Zawawi','government','Member of the Dewan Rakyat','Igan','Sarawak','Ahmad Johnie Zawawi represents Igan, Sarawak, in the Dewan Rakyat. Affiliated with PBB.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4246','/portraits/ahmad-johnie-zawawi.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P207.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4246"}, {"label": "PBB · current 2025–2028 council", "url": "https://suarasarawak.my/senarai-penuh-majlis-kerja-tertinggi-mkt-pbb-sesi-2025-2028/"}]'::jsonb from public.entities parent where parent.slug='pbb' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'huang-tiong-sii','Huang Tiong Sii','government','Deputy Minister of Plantation and Commodities','Sarikei','Sarawak','Huang Tiong Sii represents Sarikei, Sarawak, in the Dewan Rakyat. Current role: Deputy Minister of Plantation and Commodities. Affiliated with SUPP.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4247','/portraits/huang-tiong-sii.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P208.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4247"}, {"label": "SUPP · Sarikei branch chair, 2025–2027 term", "url": "https://utusansarawak.com.my/tiong-sii-dipilih-semula-pengerusi-supp-sarikei/"}]'::jsonb from public.entities parent where parent.slug='supp' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('yusuf-abd-wahab','ahmad-johnie-zawawi','huang-tiong-sii') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0060: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0060:yusuf-abd-wahab:tanjung-manis-construction-skills','Deliver the Bina Komuniti Tanjung Manis skills programme','Education','achieved',null,null,null,null,'2026-09-06','https://ukas.sarawak.gov.my/web/subpage/news_view/47997','Yusuf, also CIDB chair, launched the joint community programme with ABM construction-skills activities, including decorative painting and roof-truss installation.','Achieved covers delivery of the reported programme session. CIDB, ABM, Puspanita and local partners shared responsibility. Participant certification, sustained employment, income gains and completed repair works were not established.','2026-11-10','editorial',false from public.entities e where e.slug='yusuf-abd-wahab' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0060:huang-tiong-sii:sarikei-mrp-grants-19','Present MRP assistance to 19 Sarikei organisations','Community Development','achieved',null,null,null,null,'2026-08-20','https://www.utusanborneo.com.my/2026/08/20/huang-salur-projek-mrp-kepada-19-penerima','Huang presented grant cheques to schools, associations and community organisations at the 19 August Sarikei constituency ceremony.','The 20 August report describes the previous day’s ceremony. Achieved covers the presentation only; the article does not give a total amount or prove completed recipient projects or later spending.','2026-11-10','editorial',false from public.entities e where e.slug='huang-tiong-sii' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

